async function retry(attempt: () => Promise<boolean>, delays: number[]): Promise<void> {
  for (let index = 0; index <= delays.length; index++) {
    if (index > 0) {
      await new Promise((resolve) => setTimeout(resolve, delays[index - 1]));
    }
    if (await attempt()) {
      return;
    }
  }
}
